function leagueAverageRule(name){const key=normEntry(name),saved=state.settings?.leagueAverageRules?.[key];if(saved?.mode==='establish')return{mode:'establish',games:Math.max(1,Number(saved.games)||9)};if(saved?.mode==='carry')return{mode:'carry',games:0};return personalDefaultLeagueRule(name)}
function leagueRuleLabel(rule){return rule?.mode==='establish'?`Establish after ${rule.games} actual games`:'Carry book average forward'}
function leagueRuleNames(){return distinctEntries(state.sessions.map(leagueName).filter(n=>n&&normEntry(n)!=='practice'))}
function renderLeagueRuleSettings(){const sel=$('leagueRuleLeague');if(!sel)return;const current=sel.value,names=leagueRuleNames();sel.replaceChildren(new Option('Choose league',''),...names.map(n=>new Option(n,n)));sel.value=names.find(n=>normEntry(n)===normEntry(current))||'';if(!sel.value&&names.length)sel.value=names[0];renderLeagueRuleEditor()}
