async function saveLeagueAverageRule(){const name=$('leagueRuleLeague')?.value||'';if(!name)return toast('Choose a league first');const mode=$('leagueRuleMode').value,games=Math.max(1,Math.min(99,Number($('leagueRuleGames').value)||9));state.settings.leagueAverageRules=state.settings.leagueAverageRules||{};state.settings.leagueAverageRules[normEntry(name)]={name,mode,games:mode==='establish'?games:0};state.settingsUpdatedAt=nowIso();await saveState();renderAll();if(cloudUser())syncCloudNow().catch(()=>{});toast(`${name}: ${leagueRuleLabel(leagueAverageRule(name))} saved`)}
function leagueRunningByName(name){return name?runningLeagueAverage(leagueSessionsByName(name),leagueAverageRule(name)):null}
function namedSessionsByName(name,excludeId='',bowlerId=ownerBowlerId){const key=normEntry(name);if(!key)return[];return sessionsForBowler(bowlerId).filter(s=>s.id!==excludeId&&normEntry(leagueName(s))===key)}
